DROP VIEW IF EXISTS `HumanResources_vEmployeeDepartment`;
CREATE VIEW `HumanResources_vEmployeeDepartment` AS
select `e`.`BusinessEntityID` AS `BusinessEntityID`,`p`.`Title` AS `Title`,`p`.`FirstName` AS `FirstName`,`p`.`MiddleName` AS `MiddleName`,`p`.`LastName` AS `LastName`,`p`.`Suffix` AS `Suffix`,`e`.`JobTitle` AS `JobTitle`,`d`.`Name` AS `Department`,`d`.`GroupName` AS `GroupName`,`edh`.`StartDate` AS `StartDate` from (((`adventureworks`.`HumanResources_Employee` `e` join `adventureworks`.`Person_Person` `p` on((`p`.`BusinessEntityID` = `e`.`BusinessEntityID`))) join `adventureworks`.`HumanResources_EmployeeDepartmentHistory` `edh` on((`e`.`BusinessEntityID` = `edh`.`BusinessEntityID`))) join `adventureworks`.`HumanResources_Department` `d` on((`edh`.`DepartmentID` = `d`.`DepartmentID`))) where (`edh`.`EndDate` is null)